def generate(rng):
    # Sparse canvas containing several separated copies of a distinctive 3-by-4 shape.
    h = rng.randint(5, 20); w = rng.randint(5, 20)
    g = [[0 for _ in range(w)] for _ in range(h)]
    colors = [2, 3, 4, 5, 6, 7, 8, 9]
