    used=[]
    for k in range(n):
        col = rng.choice(colors)
        # use the canonical motif, occasionally transpose it
        trans = rng.random() < .25
        oh, ow = (4,3) if trans else (3,4)
        spots=[]
        for r in range(h-oh+1):
            for c in range(w-ow+1):
                if all(g[r+dr][c+dc]==0 for dr in range(oh) for dc in range(ow)):
                    spots.append((r,c))
        if not spots: continue
        r,c=rng.choice(spots)
        if not trans:
            cells=[(0,0),(0,3),(1,1),(1,2),(2,1),(2,2)]
        else:
            cells=[(0,0),(3,0),(1,1),(2,1),(1,2),(2,2)]
        for dr,dc in cells: g[r+dr][c+dc]=col
